// الصفوف ووحداتها بترتيب المنهج — يجب أن تطابق UNITS في backend/lib.js
const GRADES={
  1:{name:"أول ثانوي",units:["in","kv","ff","nw","vc","pc"]},
  2:{name:"ثاني ثانوي",units:["g","r","m","w","p","h"]},
  3:{name:"ثالث ثانوي",units:["fl","wv","dp","lt","mr","ln","if","es","ef","ec","ci","mg","rh","ei","em","qt","at","ss","nu"]},
};
const GRADE_OF=Object.fromEntries(Object.entries(GRADES).flatMap(([g,x])=>x.units.map(u=>[u,+g])));
const LETTERS=["أ","ب","ج","د"];
const UNIT_KEYS=Object.values(GRADES).flatMap(x=>x.units);
// اسم مختصر لمجموعة وحدات: «كل الوحدات»، أو «كل وحدات ثالث ثانوي»، أو أسماء الوحدات (أو عددها إن كثرت).
const unitsLabel=u=>{
  if(!u||!u.length||u.length>=UNIT_KEYS.length)return "كل الوحدات";
  const set=new Set(u), full=Object.values(GRADES).filter(x=>x.units.every(k=>set.has(k)));
  if(full.length&&full.reduce((n,x)=>n+x.units.length,0)===set.size)return full.map(x=>"كل وحدات "+x.name).join(" و");
  return u.length>3?`${u.length} وحدات`:u.map(k=>TOPICS[k]||k).join("، ");
};
